# ── small helpers for html blocks ──────────────────────────────────────
def md(t):
    t = _h.escape(t, quote=False)
    t = _re.sub(r"\*\*(.+?)\*\*", r"<b>\1</b>", t)
    return _re.sub(r"\*(.+?)\*", r"<i>\1</i>", t)

def p(t, cls=""):
    c = f' class="{cls}"' if cls else ""
    return f"<p{c}>{md(t)}</p>"

def lines(n):
    return '<div class="write">' + "<i></i>" * n + "</div>"

def opts(items, lead=""):
    """Choices to circle, spaced out on one line."""
    l = f"<b>{md(lead)}</b> " if lead else ""
    return f'<p class="opts">{l}' + "".join(f"<span>{md(i)}</span>" for i in items) + "</p>"

def box(label, paras, url=True, extra=""):
    """A Mini Museum box with its own label (the build's connection box is
       always 'Mini Museum connection')."""
    u = f'<p class="url">{SITE}</p>' if url else ""
    return f'<aside class="conn"><p class="label">{md(label)}</p>' + "".join(p(x) for x in paras) + extra + u + "</aside>"

def match(left, right):
    """Draw a line from each item on the left to one on the right."""
    col = lambda xs, side: f'<div class="mcol {side}">' + "".join(f"<span>{md(x)}</span>" for x in xs) + "</div>"
    return f'<div class="match">{col(left, "l")}<div></div>{col(right, "r")}</div>'

def ql(label, n=1):
    """A question with its first writing line running on from it."""
    return f'<div class="ql"><b>{md(label)}</b><i></i></div>' + (lines(n - 1) if n > 1 else "")

def bl(w=110):
    return f'<span class="bl" style="width:{w}pt"></span>'

EYE = lambda which, w: f'<img class="eye" src="%%{which}%%" alt="" style="width:{w}">'

