def ptask(n, title, body):
    """A numbered task heading as html, to keep it with what follows."""
    return (f'<section class="task numbered"><span class="pnum">{n:02d}</span><div><p class="label">Part {n}</p>'
            f'<h3>{md(title)}</h3>' + "".join(p(x) for x in body) + "</div></section>")

def say(*ps):
    """Words for the teacher to say, set apart."""
    return "<blockquote class=\"say\">" + "".join(p(x) for x in ps) + "</blockquote>"

def handout(subject, key, level, title, out, blocks, context, hero, css=""):
    return {"out": G + key + "/" + out, "eyebrow": "Student handout", "title": title,
            "sub": f"Grades 5–8 · {subject}", "level": level, "context": context,
            "foot": f"{'Handout' if len(subject) > 8 else 'Student Handout'} · Grades 5–8 {subject} · {level.title()} Level",
            "blocks": blocks, "hero": hero, "css": CSS + css}

