# ── the eye diagrams, from the original Science PDFs ───────────────────
EYE_LABELED = "data:image/jpeg;base64,"
EYE_BLANK = "data:image/jpeg;base64,"

def _eyes(v):
    if isinstance(v, str):
        return v.replace("%%EYE_LABELED%%", EYE_LABELED).replace("%%EYE_BLANK%%", EYE_BLANK)
    if isinstance(v, dict):
        return {k: _eyes(x) for k, x in v.items()}
    if isinstance(v, (list, tuple)):
        return type(v)(_eyes(x) for x in v)
    return v

DOCS = [_eyes(d) for d in DOCS]
